using System.Buffers.Binary;
namespace SoloCamera.Windows;
public static class ScreenLiveTest {
 static async Task VerifyObs(string url,string configPath,string report,List<string> results){using var config=System.Text.Json.JsonDocument.Parse(await File.ReadAllTextAsync(configPath));using var obs=new ObsBridge();double peak=0;string name="Solo Camera · Live QA "+Guid.NewGuid().ToString("N")[..6],source=name+" Feed",previous="";bool scene=false,input=false;obs.Event+=data=>{if(data.GetProperty("eventType").GetString()!="InputVolumeMeters")return;foreach(var item in data.GetProperty("eventData").GetProperty("inputs").EnumerateArray())if(item.GetProperty("inputName").GetString()==source)foreach(var channel in item.GetProperty("inputLevelsMul").EnumerateArray())foreach(var level in channel.EnumerateArray())peak=Math.Max(peak,level.GetDouble());};await obs.Connect(config.RootElement.GetProperty("server_port").GetInt32(),config.RootElement.GetProperty("server_password").GetString()!,65536);foreach(string request in new[]{"GetRecordStatus","GetStreamStatus"})if((await obs.Request(request)).GetProperty("outputActive").GetBoolean())throw new IOException("OBS is recording/streaming; isolated source test skipped");previous=(await obs.Request("GetCurrentProgramScene")).GetProperty("currentProgramSceneName").GetString()!;try{await obs.Request("CreateScene",new{sceneName=name});scene=true;await obs.Request("CreateInput",new{sceneName=name,inputName=source,inputKind="browser_source",inputSettings=new{url,width=1280,height=720,fps=30,reroute_audio=true,shutdown=true},sceneItemEnabled=true});input=true;await obs.Request("SetCurrentProgramScene",new{sceneName=name});for(int i=0;i<30;i++){await Task.Delay(200);await obs.Request("GetStats");}var screenshot=await obs.Request("GetSourceScreenshot",new{sourceName=name,imageFormat="png",imageWidth=640,imageHeight=360});string image=screenshot.GetProperty("imageData").GetString()!;await File.WriteAllBytesAsync(Path.ChangeExtension(report,"obs.png"),Convert.FromBase64String(image[(image.IndexOf(',')+1)..]));if(peak<.001)throw new IOException("OBS browser audio meter remained silent");results.Add($"PASS OBS browser source rendered and audio meter peak {peak:F4}");}finally{if(previous!="")await obs.Request("SetCurrentProgramScene",new{sceneName=previous});if(input)await obs.Request("RemoveInput",new{inputName=source});if(scene)await obs.Request("RemoveScene",new{sceneName=name});}}
 public static async Task Run(string keyFile,string report,string? obsConfig=null){var results=new List<string>();using var phone=new PhoneConnection();using var server=new LocalFeedServer([phone,new(),new(),new()]){Mode=0};try{phone.Connect("127.0.0.1",(await File.ReadAllTextAsync(keyFile)).Trim(),48732);for(int i=0;i<200&&phone.Frames<5;i++){await Task.Delay(100);if(!phone.Running)throw new IOException(phone.Status);}if(phone.Frames<5)throw new IOException("No screen frames: "+phone.Status);using var http=new HttpClient();long audioAfter=0;int packets=0;long first=phone.Frames;double power=0;long samples=0;long previousTime=-1;using var pcm=new MemoryStream();for(int i=0;i<200;i++){var response=await http.GetAsync(server.Url.Replace("/feed","/audio/0")+"?after="+audioAfter);if(response.IsSuccessStatusCode&&response.StatusCode!=System.Net.HttpStatusCode.NoContent){byte[] data=await response.Content.ReadAsByteArrayAsync();for(int p=0;p+24<=data.Length;){long seq=BinaryPrimitives.ReadInt64BigEndian(data.AsSpan(p)),time=BinaryPrimitives.ReadInt64BigEndian(data.AsSpan(p+8));int rate=BinaryPrimitives.ReadInt32BigEndian(data.AsSpan(p+16)),size=BinaryPrimitives.ReadInt32BigEndian(data.AsSpan(p+20));if(seq<=audioAfter||time<=previousTime||rate!=48000||size<2||p+24+size>data.Length)throw new IOException("Invalid audio ordering/format");audioAfter=seq;previousTime=time;packets++;p+=24;pcm.Write(data,p,size);for(int n=0;n<size;n+=2){double sample=BinaryPrimitives.ReadInt16LittleEndian(data.AsSpan(p+n))/32768.0;power+=sample*sample;samples++;}p+=size;}}await Task.Delay(50);}long frames=phone.Frames-first;if(frames<30)throw new IOException("Screen feed stalled");if(packets<50||samples<48000||Math.Sqrt(power/Math.Max(1,samples))<.001)throw new IOException("Missing/silent audio");var frame=phone.Latest??throw new IOException("No final frame");if(frame.SourceUs<=0||Math.Abs(frame.SourceUs-previousTime)>1_000_000)throw new IOException("Audio/video clocks diverged by more than one second");await File.WriteAllBytesAsync(Path.ChangeExtension(report,"jpg"),frame.Jpeg);results.Add($"PASS encrypted phone screen: {frames} frames in approximately 10 seconds");results.Add($"PASS {packets} ordered 48kHz PCM packets; RMS {Math.Sqrt(power/samples):F4}; A/V source clocks within one second");using(var file=File.Create(Path.ChangeExtension(report,"wav"))){using var writer=new BinaryWriter(file);writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));writer.Write((int)pcm.Length+36);writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(48000);writer.Write(96000);writer.Write((short)2);writer.Write((short)16);writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));writer.Write((int)pcm.Length);pcm.Position=0;pcm.CopyTo(file);}await File.WriteAllTextAsync(Path.ChangeExtension(report,"url"),server.Url);if(obsConfig!=null)await VerifyObs(server.Url,obsConfig,report,results);results.Add("RUNNING local OBS feed for 10 seconds");await File.WriteAllLinesAsync(report,results);await Task.Delay(10000);results.Add("SUCCESS");}catch(Exception e){results.Add("FAIL "+e);}finally{phone.Disconnect();await File.WriteAllLinesAsync(report,results);}}
}
